public function handle(UploadedFile $csvFile, Member $member): CsvImportResultInterface
{
    $handler = new StockMoveInstructionCsvImportHandler(
        $this->entityManager,
        $this->stockMoveInstructionRepository,
        $this->stockMoveTransferRepository,
        $this->translator,
    );

    $importer = new StockMoveInstructionCsvImporter(
        $this->entityManager,
        $this->translator,
        $this->eccubeConfig,
        $handler,
        $member,
    );

    return $importer->import($csvFile);
}

